<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="csrf-token" content="{{ csrf_token() }}"><meta name="theme-color" content="#173f32"><title>Staff register · Everbranch</title>
<style>
:root{font:16px system-ui;color:#163e31;background:#f4f5ef}*{box-sizing:border-box}body{margin:0}header{background:#173f32;color:#fff;padding:22px max(20px,calc((100vw - 1040px)/2));display:flex;justify-content:space-between;align-items:center}header strong{font-size:20px}header span{font-size:13px;color:#d3e3d7}main{max-width:1080px;margin:auto;padding:24px 20px 56px}h1{font-size:30px;letter-spacing:-1px;margin:6px 0 10px}h2{font-size:20px;margin:0 0 16px}p{line-height:1.5}.muted{color:#587064;font-size:14px}.layout{display:grid;grid-template-columns:1.4fr 1fr;gap:22px;align-items:start}.panel{background:#fff;border:1px solid #dce3d9;border-radius:18px;padding:22px;margin:20px 0}.layout .panel{margin:0}label{display:block;font-size:14px;font-weight:600;margin:16px 0 7px}select,input,button{font:inherit;min-height:46px;border-radius:9px}select,input{border:1px solid #bfcdbf;padding:10px;width:100%;background:white}button{cursor:pointer;border:1px solid #174633;background:#174633;color:white;padding:10px 16px;font-weight:600}button:disabled{opacity:.5;cursor:wait}.secondary{background:white;color:#174633;border-color:#bccabc}.wide{width:100%;margin-top:15px}.item{display:flex;justify-content:space-between;gap:12px;align-items:center;padding:16px 0;border-bottom:1px solid #e7ece4}.item:first-child{padding-top:0}.item input{width:72px}.item strong{display:block;font-size:16px}.item small{display:block;color:#587064;margin-top:5px}.line{display:flex;justify-content:space-between;gap:12px;margin:12px 0}.total{font-size:34px;font-weight:700;margin:18px 0}.code{font:700 30px ui-monospace,monospace;letter-spacing:4px;background:#edf3ea;display:inline-block;padding:12px;border-radius:9px}.notice{border-left:4px solid #c69538;background:#fff8e8;padding:16px;border-radius:8px;line-height:1.5;margin:18px 0}.notice:empty{display:none}[hidden]{display:none!important}.receipt{white-space:pre-wrap;line-height:1.7}.enrollment{overflow-wrap:anywhere}details{margin-top:28px}summary{cursor:pointer;font-size:14px;color:#587064}code{font-size:13px}a{color:#174633}@media(max-width:700px){.layout{grid-template-columns:1fr}main{padding:20px 16px}h1{font-size:27px}.panel{padding:20px}.layout aside{position:static}header{padding:18px 16px}}@media print{header,#setup,#basket,#message,details,button,.muted{display:none!important}main{padding:0}.panel{border:0}#handoff{display:block!important}}
</style></head><body>
<header><strong>Everbranch</strong><span>Staff register</span></header>
<main><h1>Ready for the next customer.</h1><p class="muted">Build the sale here. Take payment on the authorized POS iPhone.</p>
<div id="message" class="notice" role="status" aria-live="polite"></div>
<section id="setup" class="panel"><label for="register">Your register</label><select id="register"><option value="">Choose a register</option></select><p id="register-note" class="muted"></p></section>
<form id="basket" class="layout" hidden>
<section class="panel"><h2>Products</h2><div id="products"></div><div id="printing" hidden><label for="printing-quote">Or use an approved printing quote</label><select id="printing-quote"><option value="">Choose a quote</option></select></div><button type="button" id="refresh" class="secondary wide">Refresh products</button></section>
<aside class="panel"><h2>Customer</h2><p class="muted">Leave blank for a guest sale.</p><label for="customer-name">Name · optional</label><input id="customer-name" maxlength="150" autocomplete="off"><label for="customer-email">Email · optional</label><input id="customer-email" type="email" maxlength="254" autocomplete="off"><p class="muted">Contact information is for this sale and receipt. No marketing signup.</p><button id="prepare" class="wide">Review exact total</button><p class="muted">Prices and tax are checked before the sale is sent to the iPhone. Stock is checked when payment starts.</p></aside>
</form>
<section id="handoff" class="panel" hidden><h2 id="handoff-title">Ready on the iPhone</h2><p class="muted">Match this sale code in the POS app.</p><div id="handoff-code" class="code"></div><div id="lines"></div><div id="total" class="total"></div><p id="payment-status" role="status" aria-live="polite"></p><p id="stock-note" class="muted">No payment has been taken here. This basket does not hold stock.</p><button id="check" class="secondary">Check status</button> <button id="cancel" class="secondary">Cancel waiting basket</button><button id="new" hidden>Next customer</button><button id="print" hidden class="secondary">Print receipt</button><div id="receipt" class="receipt" hidden></div></section>
<details class="enrollment"><summary>Browser enrollment</summary><p class="muted">Ask your administrator to assign this browser and your staff account to the register. A new sign-in session may need a new assignment.</p><code>{{ $bootstrap['device'] }}</code></details>
</main><script>window.posStaff = {{ Illuminate\Support\Js::from($bootstrap) }};</script><script src="{{ $bootstrap['base'].'/register.js' }}?v={{ hash_file('sha256', resource_path('js/pos-staff-register.js')) }}" defer></script>
</body></html>
